async function request<T>(url:string,init?:RequestInit):Promise<T>{const response=await fetch(url,{credentials:'same-origin',...init});let data;try{data=await response.json();}catch{throw new Error('The server returned an unreadable response. Please retry.');}if(!response.ok){if(response.status===401&&url==='/api/snapshot')throw new Error('Sign in required.');const reasons:Record<string,string>={CREW_SCHEDULE_CONFLICT:'This crew already has an overlapping assignment. Choose another crew or time.',REVISION_CONFLICT:'This record changed since you opened it. Close this form, refresh the workspace and try again.',FORBIDDEN:'Your workspace role does not permit this action.',COMPLETION_EVIDENCE_REQUIRED:'Complete all five checklist items and add a site log before submitting.',FIELD_SUBMISSION_REQUIRED:'Submit the completed field run before completing this project.',OVERPAYMENT:'The received amount exceeds the invoice balance.',UNVERIFIED_FILE:'Choose a verified photo uploaded for this project.',CUSTOMER_BOUNDARY:'The selected customer and related lead must match.',DUPLICATE_INVOICE:'An invoice of this kind already exists for this project.',INVALID_TRANSITION:'This action is not available in the record’s current state.'};throw new Error(reasons[data.error] || (String(data.error||'').startsWith('INVALID_TRANSITION')?reasons.INVALID_TRANSITION:data.error) || `Request failed (${response.status}).`);}return data as T;}
