 async function auth(e:React.FormEvent<HTMLFormElement>){e.preventDefault();if(lock.current)return;const fd=new FormData(e.currentTarget);const input=Object.fromEntries(fd.entries());if(authMode==='signup'&&String(input.password).length<8){setError('Use a password with at least 8 characters.');return;}lock.current=true;setBusy(true);setError('');try{await request('/api/auth',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...input,action:authMode})});await refresh();go('/overview');}catch(err){setError(err instanceof Error?err.message:'Unable to sign in.');}finally{lock.current=false;setBusy(false);}}
