 function empty(label:string,action?:()=>void){return <div className="empty"><div className="empty-icon"><Paintbrush/></div><h3>{query||filter!=='all'?'No matching records':`Your ${label} start here`}</h3><p>{query||filter!=='all'?'Try another search or status filter.':'Create your first record. Your workspace will stay organized as you grow.'}</p>{action&&<Button variant="outline" onClick={action}><Plus/> Create {label}</Button>}</div>;}
 function table(records:Entity[],type:string,actions?:(e:Entity)=>React.ReactNode){return <div className="table-wrap"><table><thead><tr><th>{type==='customer'||type==='lead'?'CUSTOMER / PROJECT':'NAME / REFERENCE'}</th><th>DETAILS</th><th>{['estimate','invoice','expense','bid','payment'].includes(type)?'AMOUNT':'ADDED'}</th><th>STATUS</th><th><span className="sr-only">Actions</span></th></tr></thead><tbody>{records.filter(matches).map(e=><tr key={e.id}><td><div className="identity"><span className="avatar">{entityName(e).split(' ').map(x=>x[0]).slice(0,2).join('')}</span><div>{['lead','estimate','job','invoice','customer'].includes(type)?anchor(`/${({lead:'leads',estimate:'estimates',job:'jobs',invoice:'invoices',customer:'customers'} as Record<string,string>)[type]}/${e.id}`,<strong>{entityName(e)}</strong>):<strong>{entityName(e)}</strong>}<small>{text(e,'email',e.id.slice(-8))}</small></div></div></td><td>{text(e,'address',text(e,'source',text(e,'kind',text(e,'category',text(e,'trigger','—')))))}</td><td>{['estimate','invoice','expense','bid','payment'].includes(type)?currency(e.data.totalCents??e.data.amountCents??e.data.valueCents):date(e.createdAt)}</td><td><Badge value={status(e)}/></td><td><div className="row-actions">{actions?.(e)}</div></td></tr>)}</tbody></table>{records.filter(matches).length===0&&empty(type)}</div>;}
