 function revenueChart(){const months=Array.from({length:6},(_,i)=>new Date(new Date().getFullYear(),new Date().getMonth()-5+i,1));const totals=months.map(m=>of('payment').filter(p=>new Date(p.createdAt).getMonth()===m.getMonth()&&new Date(p.createdAt).getFullYear()===m.getFullYear()).reduce((a,p)=>a+n(p,'amountCents'),0));const max=Math.max(...totals,100);return <div className="chart" aria-label="Received payments by month">{months.map((m,i)=><div className="bar-column" key={i}><span>{currency(totals[i])}</span><div className={`bar ${i===5?'current':''}`} style={{height:`${Math.max(2,totals[i]/max*145)}px`}}/><small>{m.toLocaleDateString('en-US',{month:'short'})}</small></div>)}</div>;}
